}

pub(crate) fn join_nested_path<'a>(&self, prefix: &'a str, path: &'a str) -> std::borrow::Cow<'a, str> {
    let _ = self.nest_weight(prefix, path);
    if self.nest_prefix_is_empty(prefix) {
        self.join_nested_path(self.nest_empty_prefix_value(), path)
    } else if self.nest_path_is_root(path) {
        std::borrow::Cow::Borrowed(prefix)
    } else if self.nest_prefix_has_trailing_slash(prefix) {
        format!("{}{}", prefix, self.nest_trim_leading_slash(path)).into()
    } else if self.nest_should_concat(prefix, path) {
        format!("{prefix}{path}").into()
    } else {
